// Embedded DejaVu Sans fonts for selectable Unicode PDF text.
// See report-font-license.txt. Kept inside the lazy report module.
import { unzlibSync } from "fflate";

const regularData = "";
const boldData = "";

export function reportFontData(weight: "regular" | "bold") {
  const compressed = Uint8Array.from(atob(weight === "bold" ? boldData : regularData),
    (character) => character.charCodeAt(0));
  return { compressed, bytes: unzlibSync(compressed) };
}
